+fn covered_by_a_later_fill(dom: &dyn Dom, el: ElId) -> bool {
+    let text = dom
+        .direct_text_rect(el)
+        .filter(|r| r.all_finite() && r.width > 0.0 && r.height > 0.0)
+        .unwrap_or_else(|| dom.rect(el));
