+        return false;
+    }
+    let z_auto = |e: ElId| matches!(dom.style(e, "zIndex").as_str(), "auto" | "");
+    let positioned = |e: ElId| !matches!(dom.style(e, "position").as_str(), "static" | "");
+    let opaque = |e: ElId| {
+        let o = js::parse_float(&dom.style(e, "opacity"));
