+        return false;
+    };
+    if bg.alpha_or_one() < FILL_COVER_MIN_ALPHA {
+        return false;
+    }
+    let clip = dom.style(fill, "backgroundClip");
+    let webkit_clip = dom.style(fill, "webkitBackgroundClip");
