+            return false;
+        }
+        alpha *= js::parse_float(&dom.style(c, "opacity"));
+        if !(alpha >= FILL_COVER_MIN_ALPHA) {
+            return false;
+        }
+        layered |= positioned(c);
+        if c == sib {
+            break;
+        }
+        cur = dom.parent(c);
+    }
